_LANGS = {
    "ko": _KO,
    "en": _EN,
}

_DEFAULT_LANG = "ko"
_ACTIVE_LANG = "en" if str(globals().get("APP_LANGUAGE", "ko")).lower().startswith("en") else "ko"


def set_language(lang: str) -> str:
    """출력 문구에 사용할 언어를 바꾼다(고정 UI 라벨은 앱을 다시 실행할 때 적용)."""
    global _ACTIVE_LANG
    _ACTIVE_LANG = "en" if str(lang).lower().startswith("en") else "ko"
    return _ACTIVE_LANG


def get_language() -> str:
    return _ACTIVE_LANG


def _merge_lang(base: dict, over: dict) -> dict:
    merged = dict(base)
    for key, value in (over or {}).items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = {**merged[key], **value}
        else:
            merged[key] = value
    return merged


_LANG_CACHE = {}


def get_strings(lang=None) -> dict:
    """언어별 문구를 돌려준다. 영어에 없는 항목은 한국어 원문으로 자동 대체된다."""
    key = str(lang or _ACTIVE_LANG)
    if key not in _LANGS:
        key = _DEFAULT_LANG
    if key == _DEFAULT_LANG:
        return _LANGS[_DEFAULT_LANG]
    if key not in _LANG_CACHE:
        _LANG_CACHE[key] = _merge_lang(_LANGS[_DEFAULT_LANG], _LANGS[key])
    return _LANG_CACHE[key]


class _LangSection:
    """언어가 바뀌면 곧바로 반영되는 문구 묶음(모듈 상단에서 미리 잡아두는 용도)."""

    __slots__ = ("_section",)

    def __init__(self, section=None):
        self._section = section

    def _resolve(self):
        data = get_strings()
        return data[self._section] if self._section else data

    def __getitem__(self, key):
        return self._resolve()[key]

    def get(self, key, default=None):
        return self._resolve().get(key, default)

    def __contains__(self, key):
        return key in self._resolve()

    def keys(self):
        return self._resolve().keys()

    def items(self):
        return self._resolve().items()

    def values(self):
        return self._resolve().values()

    def __iter__(self):
        return iter(self._resolve())

    def __len__(self):
        return len(self._resolve())


def _as_bool(series) -> "pd.Series":
    """결측을 False로 본 불리언 시리즈를 만든다.

    object dtype 컬럼에 .fillna(False)를 쓰면 pandas가 downcasting FutureWarning을
    쏟아내므로, 다운캐스팅에 기대지 않고 명시적으로 변환한다. 값 자체는 기존과 동일하다.
    """
    import numpy as _np
    import pandas as _pd
    if series is None:
        return _pd.Series(dtype=bool)
    s = series if isinstance(series, _pd.Series) else _pd.Series(series)
    arr = s.to_numpy(dtype=object, copy=True)
    out = _np.zeros(len(arr), dtype=bool)
    for i, v in enumerate(arr):
        if v is None:
            continue
        try:
            if isinstance(v, float) and _np.isnan(v):
                continue
        except Exception:
            pass
        out[i] = bool(v)
    return _pd.Series(out, index=s.index, dtype=bool)


def _safe_num(value, default=float('nan')) -> float:
    """None·빈 문자열·변환 불가 값을 예외 없이 숫자로 바꾼다.

    dict.get(key, default)는 키가 있고 값이 None이면 None을 돌려주므로
    float(None)에서 터진다. 손상되거나 스키마가 다른 프로젝트를 불러왔을 때
    Trial 저장이 통째로 실패하던 원인이라 안전한 변환을 쓴다.
    """
    if value is None:
        return default
    try:
        out = float(value)
    except (TypeError, ValueError):
        return default
    return out


def localize_columns(df, lang=None):
    if df is None or getattr(df, "empty", True):
        return df
    labels = get_strings(lang).get("column_labels", {})
    rename_map = {col: labels[col] for col in df.columns if col in labels}
    return df.rename(columns=rename_map)


UI_TABLE_MAX_ROWS = 1500


def _ui_table(df, lang=None):
    """화면 표시용 표를 만든다. 행이 너무 많으면 앞뒤만 잘라 보낸다
    (Colab 프록시가 거대한 응답을 HTML 오류로 되돌려 'Unexpected token <' 가 뜨는 것을 막는다).
    CSV/JSON/XLSX Export는 이 함수를 쓰지 않으므로 전체 데이터가 그대로 저장된다."""
    out = localize_columns(df, lang)
    if out is None or getattr(out, "empty", True):
        return out
    try:
        n = len(out)
        if n > UI_TABLE_MAX_ROWS:
            head_n = UI_TABLE_MAX_ROWS // 2
            tail_n = UI_TABLE_MAX_ROWS - head_n
            logger.info(f"표가 커서 화면에는 {UI_TABLE_MAX_ROWS}행만 표시합니다(전체 {n}행). "
                        f"전체 데이터는 Export로 저장하세요.")
            return pd.concat([out.head(head_n), out.tail(tail_n)])
    except Exception:
        return out
    return out

                                                                              
