import numpy as np
import pandas as pd


class _OpticalFlowTracker:
    def __init__(self):
        self.prev_gray = None
        self.points = None
        self.bbox = None

    def init(self, frame, bbox):
        x, y, w, h = bbox
        self.bbox = (float(x), float(y), float(w), float(h))
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        x0, y0 = max(0, int(x)), max(0, int(y))
        x1, y1 = min(gray.shape[1], int(x + w)), min(gray.shape[0], int(y + h))
        pts = None
        if x1 > x0 and y1 > y0:
            roi = gray[y0:y1, x0:x1]
            found = cv2.goodFeaturesToTrack(roi, maxCorners=30, qualityLevel=0.01, minDistance=4)
            if found is not None:
                found[:, 0, 0] += x0
                found[:, 0, 1] += y0
                pts = found
        self.points = pts
        self.prev_gray = gray
        return True

    def update(self, frame):
        if self.prev_gray is None or self.points is None or len(self.points) < 3:
            return False, (0, 0, 0, 0)
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        new_pts, status, _ = cv2.calcOpticalFlowPyrLK(self.prev_gray, gray, self.points, None)
        if new_pts is None or status is None:
            return False, (0, 0, 0, 0)
        mask = status.reshape(-1) == 1
        good_new = new_pts[mask]
        good_old = self.points[mask]
        if len(good_new) < 3:
            return False, (0, 0, 0, 0)
        dx = float(np.median(good_new[:, 0, 0] - good_old[:, 0, 0]))
        dy = float(np.median(good_new[:, 0, 1] - good_old[:, 0, 1]))
        x, y, w, h = self.bbox
        x, y = x + dx, y + dy
        self.bbox = (x, y, w, h)
        self.points = good_new.reshape(-1, 1, 2)
        self.prev_gray = gray
        return True, (x, y, w, h)


class ShuttlecockCenterEstimator:
    """셔틀콕의 '대표 위치(center position)'를 한 가지 기준으로 일관되게 추정한다.

    연구에서 필요한 것은 시각적으로 가장 잘 보이는 부분의 위치가 아니라, 모든 프레임에서
    같은 정의로 계산된 중심이다. 그래서 이 클래스는 후보 중심을 여러 개 계산해 두되,
    한 번 고른 정의(method)를 촬영 조건·손상 조건이 달라져도 그대로 유지한다.

    후보 중심
      bbox              : 추적 상자의 기하 중심 (마스크가 없어도 항상 계산됨)
      mask_centroid     : 분리된 물체 마스크의 1차 모멘트 중심
      weighted_centroid : 마스크 안에서 밝기 x 내부거리로 가중한 중심
                          (깃털 끝처럼 얇은 부분의 기여를 줄인다)
      cork_center       : 마스크 안에서 가장 밝고 뭉쳐 있는 덩어리(코르크)의 중심

    깃털이 빠진 셔틀콕은 mask_centroid 가 남은 깃털 쪽으로 끌려가므로, 손상 조건을
    비교하는 실험에서는 cork_center 또는 weighted_centroid 가 조건 사이에서 더 일관된
    기준이 된다. 다만 어떤 기준을 쓸지는 연구자가 고르거나(auto 가 아닌 값) 첫 프레임에서
    한 번 정해지고, 그 뒤로는 바뀌지 않는다.
    """

    METHODS = ("auto", "bbox", "mask_centroid", "weighted_centroid", "cork_center", "blended")

    @staticmethod
    def _filled_mask(mask: Optional[np.ndarray], keep_thin: bool = False) -> Optional[np.ndarray]:
        """마스크를 이진화하고 내부 구멍을 메운다.

        keep_thin=False (기본, 일반 물체) 에서는 '가장 두꺼운 덩어리만 남기기'
        (_core_blob_mask)로 막대·실처럼 물체를 가로지르는 구조물을 걸러낸다. 진자의 실이
        상자를 지나가는 경우가 대표적이다.

        keep_thin=True (셔틀콕) 에서는 그 처리를 쓰지 않는다. 깃털 스커트는 얇지만 물체의
        일부이고, 스커트를 지우면 mask centroid 와 weighted centroid 가 코르크 중심과
        같아져 네 가지 중심 정의가 하나로 붕괴한다. 그러면 어느 정의가 나은지 비교하는 것
        자체가 불가능해진다. 다만 마스크가 패치의 60% 를 넘게 덮으면(=배경까지 삼켰을
        가능성이 큰 경우) 이때는 덩어리 추출로 되돌린다.
        """
        if mask is None or mask.size == 0:
            return None
        binary = np.where(mask > 128, 255, 0).astype(np.uint8)
        if int(np.count_nonzero(binary)) < 6:
            return None
        h, w = binary.shape[:2]
        if (not keep_thin) or float(np.count_nonzero(binary)) > 0.60 * float(binary.size):
            core = VideoProcessor._core_blob_mask(binary, (w / 2.0, h / 2.0))
            if core is not None:
                binary = core
        return VideoProcessor._fill_mask_holes(binary, (w / 2.0, h / 2.0))

    @staticmethod
    def _cork_blob(gray: np.ndarray, filled: np.ndarray) -> Optional[np.ndarray]:
        """마스크 안에서 코르크로 볼 수 있는 '밝고 뭉친' 부분만 남긴다.

        코르크는 깃털 스커트보다 밝고 속이 차 있어서, 마스크 내부 밝기의 상위 분위수로
        자른 뒤 가장 큰 연결 성분을 고르면 대체로 코르크가 남는다. 밝기 대비가 없어
        분위수 컷이 마스크 전체를 그대로 남기면(=구분 실패) None 을 돌려준다.
        """
        vals = gray[filled > 0]
        if vals.size < 12:
            return None
        lo, hi = float(np.percentile(vals, 25)), float(np.percentile(vals, 95))
        if hi - lo < 8.0:
            return None
        thresh = float(np.percentile(vals, 70))
        bright = ((gray >= thresh) & (filled > 0)).astype(np.uint8)
        if int(np.count_nonzero(bright)) < 6:
            return None
        try:
            n, labels, stats, _cent = cv2.connectedComponentsWithStats(bright, 8)
        except Exception:
            return None
        if n <= 1:
            return None
        areas = stats[1:, cv2.CC_STAT_AREA]
        pick = int(np.argmax(areas)) + 1
        blob = (labels == pick).astype(np.uint8) * 255
        area = float(np.count_nonzero(blob))
        total = float(np.count_nonzero(filled))
        if area < 6.0 or area > 0.85 * total:
            return None
        return blob

    @staticmethod
    def candidates(patch_bgr: Optional[np.ndarray],
                   mask: Optional[np.ndarray] = None,
                   keep_thin: bool = True) -> Dict[str, Tuple[float, float]]:
        """패치 좌표계에서 계산 가능한 중심 후보를 모두 돌려준다.

        keep_thin 은 깃털 스커트처럼 얇은 부분을 마스크에 남길지 정한다(_filled_mask 참고).
        셔틀콕에서는 남겨야 하므로 기본값이 True 다.
        """
        out: Dict[str, Tuple[float, float]] = {}
        if patch_bgr is None or patch_bgr.size == 0:
            return out
        ph, pw = patch_bgr.shape[:2]
        out["bbox"] = (pw / 2.0, ph / 2.0)
        gray = cv2.cvtColor(patch_bgr, cv2.COLOR_BGR2GRAY) if patch_bgr.ndim == 3 else patch_bgr
        filled = ShuttlecockCenterEstimator._filled_mask(
            mask if mask is not None else VideoProcessor._segment_object_mask(patch_bgr, dilate=False),
            keep_thin=keep_thin)
        if filled is None:
            return out

        try:
            mom = cv2.moments(filled, binaryImage=True)
            if mom.get("m00", 0.0) > 4.0:
                out["mask_centroid"] = (float(mom["m10"] / mom["m00"]),
                                        float(mom["m01"] / mom["m00"]))
        except Exception:
            pass

        # 밝기 x 내부거리 가중: 깃털 끝(얇고 어두움)의 기여를 줄여 흔들림을 억제한다.
        try:
            dist = cv2.distanceTransform(filled, cv2.DIST_L2, 5)
            g = gray.astype(np.float32)
            inside = filled > 0
            if int(np.count_nonzero(inside)) >= 6:
                gmin, gmax = float(g[inside].min()), float(g[inside].max())
                gnorm = (g - gmin) / (gmax - gmin) if gmax - gmin > 1e-6 else np.ones_like(g)
                dmax = float(dist.max())
                dnorm = dist / dmax if dmax > 1e-6 else np.ones_like(dist)
                wgt = np.where(inside, (0.5 + 0.5 * np.clip(gnorm, 0.0, 1.0)) * (0.25 + 0.75 * dnorm), 0.0)
                tot = float(wgt.sum())
                if tot > 1e-6:
                    ys, xs = np.mgrid[0:filled.shape[0], 0:filled.shape[1]]
                    out["weighted_centroid"] = (float((wgt * xs).sum() / tot),
                                                float((wgt * ys).sum() / tot))
        except Exception:
            pass

        blob = ShuttlecockCenterEstimator._cork_blob(gray, filled)
        if blob is not None:
            try:
                mom = cv2.moments(blob, binaryImage=True)
                if mom.get("m00", 0.0) > 4.0:
                    out["cork_center"] = (float(mom["m10"] / mom["m00"]),
                                          float(mom["m01"] / mom["m00"]))
            except Exception:
                pass

                                                                                     
                                                                                     
                                                                                     
        core_peak = None
        try:
            dist = cv2.distanceTransform(filled, cv2.DIST_L2, 5)
            _mn, core_r, _ml, core_loc = cv2.minMaxLoc(dist)
            if core_r is not None and float(core_r) >= 1.5:
                core_peak = (float(core_loc[0]), float(core_loc[1]))
                out["core_peak"] = core_peak
        except Exception:
            pass
        blend_src = [p for p in (out.get("mask_centroid"), core_peak) if p is not None]
        if blend_src:
            out["blended"] = (float(np.mean([p[0] for p in blend_src])),
                              float(np.mean([p[1] for p in blend_src])))
        return out

    @staticmethod
    def choose_method(cands: Dict[str, Tuple[float, float]],
                      shuttlecock: bool = True) -> str:
        """auto 일 때 쓸 중심 정의를 한 번만 고른다(이후 실행 내내 고정).

        셔틀콕에서는 손상 조건 비교가 목적이므로 남은 깃털 배치에 흔들리지 않는 기준이
        필요하다. 코르크를 찾을 수 있으면 cork_center 를, 그렇지 않으면
        weighted_centroid 를, 마스크 자체가 없으면 bbox 를 쓴다.

        셔틀콕이 아닌 경우에는 기존 동작(마스크 무게중심과 내부 최심점의 평균)을 그대로
        유지한다 — 진자·구슬처럼 다른 대상에 쓰던 결과가 이번 변경으로 달라지지 않게 하기
        위해서다.
        """
        if not shuttlecock:
            for name in ("blended", "mask_centroid", "core_peak"):
                if name in cands:
                    return name
            return "bbox"
        if "cork_center" in cands:
            return "cork_center"
        if "weighted_centroid" in cands:
            return "weighted_centroid"
        if "mask_centroid" in cands:
            return "mask_centroid"
        return "bbox"

    @staticmethod
    def estimate(patch_bgr: Optional[np.ndarray], mask: Optional[np.ndarray],
                 method: str, locked: Optional[str] = None,
                 keep_thin: bool = True) -> Optional[Dict[str, Any]]:
        """지정한 기준으로 패치 좌표계 중심과 그 신뢰도를 계산한다.

        신뢰도는 '후보들이 서로 얼마나 모여 있는가'로만 매긴다. 후보가 크게 어긋나면
        어느 정의를 쓰든 그 프레임의 중심 추정은 불안정하다는 뜻이므로 낮은 값을 준다.
        """
        cands = ShuttlecockCenterEstimator.candidates(patch_bgr, mask, keep_thin=keep_thin)
        if not cands:
            return None
                                                                                     
                                                                                     
                                                                                     
        want = str(locked or method or "bbox")
        use = want
        if use == "auto" or use not in cands:
            use = ShuttlecockCenterEstimator.choose_method(cands, shuttlecock=keep_thin)
        fallback = bool(want not in ("auto", "") and want != use)
        cx, cy = cands[use]
                                                                                     
        pts = np.asarray([v for k, v in cands.items()
                          if k not in ("core_peak", "blended")] or list(cands.values()),
                         dtype=float)
        ph, pw = patch_bgr.shape[:2]
        diag = max(4.0, float(np.hypot(pw, ph)))
        spread = float(np.max(np.hypot(pts[:, 0] - cx, pts[:, 1] - cy))) if len(pts) > 1 else 0.0
        confidence = float(np.exp(-spread / (0.35 * diag)))
                                                                                     
                                                                                     
        if fallback:
            confidence *= 0.5
        return {"cx": float(cx), "cy": float(cy), "method": use,
                "requested_method": want, "fallback": fallback,
                "confidence": float(np.clip(confidence, 0.0, 1.0)),
                "spread_px": spread, "candidates": cands}


class VideoProcessor:
    def __init__(self, min_iou_for_match: float = 0.1, appearance_threshold: float = 0.35,
                 max_jump_px: float = 150.0, max_lost_frames: int = 30):
        self.yolo = None
        self._yolo_ready = False
                                                          
                                              
        self.min_iou_for_match = min_iou_for_match
        self.appearance_threshold = appearance_threshold
        self.max_jump_px = max_jump_px
        self.max_lost_frames = max_lost_frames
        self.allow_yolo_bootstrap = False
        self.yolo_redetect_after = 5
        self.pause_on_suspicious = False
        self.initial_motion_reference: Dict[str, float] = {}
        self.resume_grace_frames = 8
        self.candidate_margin_min: float = 0.08
                                                                           
                                                                          
        self.experimental_lookahead_matching: bool = False
        self.lookahead_search_scale: float = 2.5
        self.lookahead_subpixel: bool = True
                                                                        
        self._lookahead_patches: Dict[str, np.ndarray] = {}
        self._lookahead_initial_patches: Dict[str, np.ndarray] = {}
        self.reject_ambiguous_frames: bool = True
        self.no_pause_before_frame: Optional[int] = None
        self.frame_start: int = 0
        self.frame_end: int = -1
        self.auto_segment: bool = True
        self.use_orb: bool = True
        self.template_update_rate: float = 0.10
        self.smooth_strength: float = 0.5
        self._orb_detector = None
        self._orb_matcher = None
        self.tracking_profile: str = "Generic"
        self.tracking_mode: str = "Balanced"
        self.score_weights: Dict[str, float] = {}
        self.last_pause_frame: Optional[int] = None
        self.last_pause_reason: str = ""
        self.last_tracking_stats: Dict[str, Any] = {}
        self.anchor_gate: float = 0.45
        self.reacquire_after: int = 3
        self.reacquire_min_score: float = 0.55
        self.reacquire_interval: int = 3
        self.drop_drift_rows: bool = True
        self.reject_flow_bg: bool = True
        self.strict_jump: bool = True
        self.anchor_abs_floor: float = 0.12
        self.autofit_bbox: bool = True
        self.autofit_expand: float = 2.0
        self.center_lock: bool = True
        self.center_lock_min_ratio: float = 0.12
        self.csrt_fast: bool = True
        self.use_point_tracking: bool = True
        self.orient_box: bool = True
        self.prefetch_frames: int = 8
        self.prefetch_budget_mb: int = 48
        self.share_flow_with_points: bool = True
        self.point_track_interval: int = 1
        self.point_max: int = 40
        self.point_min_inliers: int = 3
        self.anchor_lock: bool = True
        self.anchor_bank_max: int = 8
        self.use_multi_anchor: bool = True
        self.anchor_baseline_frames: int = 5
        self.process_max_side: int = 960
        self.match_interval: int = 1
        self.subpixel_refine: bool = True
        self.process_scale: float = 0.0
        self.hard_drift_ratio: float = 0.6
        self.anchor_refresh_min: float = 0.80
                                                                              
                                                                              
        self.damage_condition: str = "NORMAL"
        self.center_method: str = "auto"
        self._resolved_center_method: Optional[str] = None
                                                                              
                                                                              
        self.max_predicted_run: int = 5
                                                                              
                                                                              
        self.roi_stage_scales: Tuple[float, ...] = (2.5, 5.0, 9.0)
                                                                              
                                                                             
        self.blur_conf_penalty: float = 0.35
        self.last_center_stats: Dict[str, Any] = {}
                                                                                     
                                                                                     
                                                                                     
        self.raw_tracking_only: bool = True

    _feat_cache: Dict[Tuple[Any, ...], Any] = {}

    def _collect_benchmark(self, start_time: float, frames: int, gpu_peak: float = 0.0) -> Dict[str, Any]:
        elapsed = max(1e-9, time.perf_counter() - float(start_time))
        peak_rss = 0.0
        try:
            import resource as _resource
            usage = _resource.getrusage(_resource.RUSAGE_SELF).ru_maxrss
            peak_rss = float(usage) / (1024.0 * 1024.0) if usage > 1e7 else float(usage) / 1024.0
        except Exception:
            peak_rss = 0.0
        gpu_mb = float(gpu_peak)
        if HAS_TORCH and TORCH_CUDA:
            try:
                gpu_mb = float(torch.cuda.max_memory_allocated()) / (1024.0 * 1024.0)
            except Exception:
                gpu_mb = float(gpu_peak)
        return {
            "elapsed_sec": float(elapsed),
            "frames": int(frames),
            "fps": float(frames) / elapsed if frames else 0.0,
            "peak_rss_mb": peak_rss,
            "gpu_peak_mb": gpu_mb,
            "process_scale": float(self.get_process_scale(1920, 1080)),
            "tracker_backend": str(getattr(self, "_last_tracker_type", "")),
        }

    @staticmethod
    def _reset_feature_cache() -> None:
        """프레임이 바뀔 때 외형 특징 캐시를 비운다(같은 프레임 안에서만 재사용)."""
        VideoProcessor._feat_cache.clear()

    @staticmethod
    def _extract_template(frame: np.ndarray, bbox: Tuple[float, float, float, float],
                          mask_ref: Optional[np.ndarray] = None) -> Optional[np.ndarray]:
        x, y, w, h = bbox
        h_img, w_img = frame.shape[:2]
        x0, y0 = max(0, int(round(x))), max(0, int(round(y)))
        x1, y1 = min(w_img, int(round(x + w))), min(h_img, int(round(y + h)))
        cache = VideoProcessor._feat_cache
        ckey = ("tpl", x0, y0, x1, y1, id(mask_ref))
        if ckey in cache:
            return cache[ckey]
        if x1 - x0 < 4 or y1 - y0 < 4:
            cache[ckey] = None
            return None
        patch = frame[y0:y1, x0:x1]
        if patch.size == 0:
            cache[ckey] = None
            return None
        gray = cv2.cvtColor(patch, cv2.COLOR_BGR2GRAY) if patch.ndim == 3 else patch
        try:
            resized = cv2.resize(gray, (24, 24), interpolation=cv2.INTER_AREA).astype(np.float32)
        except Exception:
            cache[ckey] = None
            return None
        std = float(np.std(resized))
        centered = resized - float(np.mean(resized))
        if std >= 1e-6:
            centered = centered / std
        if mask_ref is not None:
            m = VideoProcessor._mask_for_patch(mask_ref, (24, 24))
            if m is not None and int(np.count_nonzero(m)) >= 4:
                wmap = m.astype(np.float32) / 255.0
                wmap = np.clip(wmap + 0.15, 0.0, 1.0)
                out = centered * wmap
                cache[ckey] = out
                return out
        if VideoProcessor._CENTER_WEIGHT is None:
            gy, gx = np.mgrid[0:24, 0:24].astype(np.float32)
            d2 = ((gx - 11.5) ** 2 + (gy - 11.5) ** 2) / (2.0 * (7.0 ** 2))
            VideoProcessor._CENTER_WEIGHT = np.exp(-d2).astype(np.float32)
        out = centered * VideoProcessor._CENTER_WEIGHT
        cache[ckey] = out
        return out

    @staticmethod
    def _extract_hist(frame: np.ndarray, bbox: Tuple[float, float, float, float],
                      mask_ref: Optional[np.ndarray] = None) -> Optional[np.ndarray]:
        x, y, w, h = bbox
        h_img, w_img = frame.shape[:2]
        x0, y0 = max(0, int(round(x))), max(0, int(round(y)))
        x1, y1 = min(w_img, int(round(x + w))), min(h_img, int(round(y + h)))
        cache = VideoProcessor._feat_cache
        ckey = ("hist", x0, y0, x1, y1, id(mask_ref))
        if ckey in cache:
            return cache[ckey]
        if x1 - x0 < 4 or y1 - y0 < 4:
            cache[ckey] = None
            return None
        patch = frame[y0:y1, x0:x1]
        if patch.size == 0:
            cache[ckey] = None
            return None
        try:
            ph, pw = patch.shape[:2]
            mask = VideoProcessor._mask_for_patch(mask_ref, (ph, pw))
            if mask is not None:
                mask = np.where(mask > 60, 255, 0).astype(np.uint8)
            if mask is None or int(np.count_nonzero(mask)) < 4:
                mask = np.zeros((ph, pw), dtype=np.uint8)
                cv2.ellipse(mask, (pw // 2, ph // 2),
                            (max(2, int(pw * 0.25)), max(2, int(ph * 0.25))), 0, 0, 360, 255, -1)
            if patch.ndim == 3:
                hsv = cv2.cvtColor(patch, cv2.COLOR_BGR2HSV)
                hist = cv2.calcHist([hsv], [0, 1, 2], mask, [12, 12, 8], [0, 180, 0, 256, 0, 256])
            else:
                hist = cv2.calcHist([patch], [0], mask, [32], [0, 256])
            cv2.normalize(hist, hist, 0, 1, cv2.NORM_MINMAX)
            cache[ckey] = hist
            return hist
        except Exception:
            cache[ckey] = None
            return None

    @staticmethod
    def _hist_similarity(frame: np.ndarray, bbox: Tuple[float, float, float, float],
                         hist_ref: Optional[np.ndarray],
                         mask_ref: Optional[np.ndarray] = None) -> float:
        if hist_ref is None:
            return 1.0
        hist = VideoProcessor._extract_hist(frame, bbox, mask_ref)
        if hist is None:
            return 0.0
        try:
            return float(cv2.compareHist(hist_ref, hist, cv2.HISTCMP_CORREL))
        except Exception:
            return 0.0

    @staticmethod
    def _appearance_score(frame: np.ndarray, bbox: Tuple[float, float, float, float],
                          template: Optional[np.ndarray],
                          hist_ref: Optional[np.ndarray] = None,
                          mask_ref: Optional[np.ndarray] = None,
                          small_object_mode: bool = False) -> float:
        """앵커 외형과 후보 영역의 일치도.

        small_object_mode 는 작고 크기가 변하는 물체(=셔틀콕)를 위한 두 가지 보정을 켠다.

        1) 배율 허용
           상자를 몇 가지 배율로 바꿔가며 비교하고 가장 잘 맞는 값을 쓴다. 셔틀콕이
           카메라에서 멀어지면 상자 안에서 물체가 차지하는 비율이 줄어드는데, 고정 배율로만
           비교하면 이것이 '외형이 달라졌다 = 놓쳤다'로 잘못 읽힌다. 실제로 달라진 것은
           크기뿐이므로, 크기를 맞춰본 뒤에도 안 맞을 때만 불일치로 본다.

        2) 색 히스토그램의 거부권 제한
           원래는 min(모양 일치도, 색 일치도) 였다. 작은 물체에서는 색 히스토그램에 들어가는
           화소가 수백 개뿐인데 빈은 1000개가 넘어, 상관계수 자체가 통계적으로 불안정하다.
           그런 값에 거부권을 주면 멀쩡한 추적이 '색이 다르다'는 이유로 버려진다. 그래서
           히스토그램에 들어간 표본 수로 신뢰도를 매기고, 표본이 적을수록 색의 영향력을
           줄인다. 표본이 충분하면 예전처럼 그대로 거부권을 갖는다.
        """
        if template is None:
            return 1.0

        def _ncc(box) -> float:
            candidate = VideoProcessor._extract_template(frame, box, mask_ref)
            if candidate is None:
                return float('nan')
            denom = float(np.linalg.norm(template) * np.linalg.norm(candidate))
            if denom < 1e-9:
                return float('nan')
            return float(np.dot(template.ravel(), candidate.ravel()) / denom)

        ncc = _ncc(bbox)
        if small_object_mode:
            bx, by, bw, bh = [float(v) for v in bbox]
            cx, cy = bx + bw / 2.0, by + bh / 2.0
            for k in (0.65, 0.8, 1.25):
                nw, nh = bw * k, bh * k
                if min(nw, nh) < 6.0:
                    continue
                alt = _ncc((cx - nw / 2.0, cy - nh / 2.0, nw, nh))
                if np.isfinite(alt) and (not np.isfinite(ncc) or alt > ncc):
                    ncc = alt
        if not np.isfinite(ncc):
            return 0.0
        if hist_ref is None:
            return ncc
        hist_sim = VideoProcessor._hist_similarity(frame, bbox, hist_ref, mask_ref)
        if small_object_mode:
            rel = VideoProcessor._hist_reliability(frame, bbox, hist_ref, mask_ref)
                                                                                     
            hist_sim = hist_sim + (1.0 - rel) * (1.0 - hist_sim)
        return float(min(ncc, hist_sim))

    @staticmethod
    def _hist_reliability(frame: np.ndarray, bbox: Tuple[float, float, float, float],
                          hist_ref: Optional[np.ndarray],
                          mask_ref: Optional[np.ndarray] = None) -> float:
        """색 히스토그램 비교를 얼마나 믿을 수 있는지 (0~1).

        두 가지를 함께 본다.

        1) 분별력 — 기준 히스토그램이 실제로 값을 가진 빈이 몇 개인가.
           흰 셔틀콕과 회색 코트처럼 색이 거의 없는 장면에서는 12x12x8 빈 중 열 개
           남짓에만 값이 몰린다. 그런 히스토그램은 물체와 배경을 구분하지 못하므로,
           상관계수가 낮게 나와도 '다른 물체'라는 증거가 되지 못한다.
        2) 표본 충분성 — 빈 하나당 화소가 몇 개나 들어갔는가.
           작은 물체는 화소 수 자체가 적어 상관계수의 분산이 크다.

        둘 중 나쁜 쪽을 신뢰도로 삼는다. 신뢰도가 낮으면 색이 외형 판정에 거부권을
        갖지 못하게 하되, 색은 점수 계산에서 color_hist 항목으로 여전히 반영된다.
        """
        if hist_ref is None:
            return 0.0
        try:
            occupied = int(np.count_nonzero(np.asarray(hist_ref) > 1e-6))
            if occupied <= 0:
                return 0.0
            x, y, w, h = [float(v) for v in bbox]
            h_img, w_img = frame.shape[:2]
            x0, y0 = max(0, int(round(x))), max(0, int(round(y)))
            x1, y1 = min(w_img, int(round(x + w))), min(h_img, int(round(y + h)))
            if x1 - x0 < 2 or y1 - y0 < 2:
                return 0.0
                                                                                     
            n_px = 0.25 * float((x1 - x0) * (y1 - y0))
            discriminative = float(np.clip(occupied / 64.0, 0.0, 1.0))
            sufficient = float(np.clip(n_px / (4.0 * occupied), 0.0, 1.0))
            return float(min(discriminative, sufficient))
        except Exception:
            return 0.0

    def _optical_flow_shift(self, prev_gray: Optional[np.ndarray], curr_gray: Optional[np.ndarray],
                            center: Tuple[float, float], box: Tuple[float, float],
                            mask_ref: Optional[np.ndarray] = None) -> Optional[Tuple[float, float]]:
        if prev_gray is None or curr_gray is None:
            return None
        cx, cy = center
        bw, bh = box
        h_img, w_img = prev_gray.shape[:2]
        opts = self.get_profile_options()
        margin = float(opts.get("flow_window", 2.0)) if self.reject_flow_bg else 2.0
        margin = max(0.6, margin)
        hw = max(4.0, bw * margin / 2.0)
        hh = max(4.0, bh * margin / 2.0)
        x0 = max(0, int(cx - hw)); y0 = max(0, int(cy - hh))
        x1 = min(w_img, int(cx + hw)); y1 = min(h_img, int(cy + hh))
        if x1 - x0 < 6 or y1 - y0 < 6:
            return None
        try:
            roi = prev_gray[y0:y1, x0:x1]
            roi_mask = None
            if mask_ref is not None and self.reject_flow_bg:
                m = VideoProcessor._mask_for_patch(mask_ref, (y1 - y0, x1 - x0))
                if m is not None and int(np.count_nonzero(m > 60)) >= 12:
                    roi_mask = np.where(m > 60, 255, 0).astype(np.uint8)
            pts = cv2.goodFeaturesToTrack(roi, maxCorners=30, qualityLevel=0.01,
                                          minDistance=3, mask=roi_mask)
            if pts is None or len(pts) < 3:
                return None
            pts[:, 0, 0] += x0
            pts[:, 0, 1] += y0
            pts = pts.astype(np.float32)
            new_pts, status, _err = cv2.calcOpticalFlowPyrLK(prev_gray, curr_gray, pts, None)
            if new_pts is None or status is None:
                return None
            ok = status.reshape(-1) == 1
            if self.reject_flow_bg:
                back_pts, back_status, _e2 = cv2.calcOpticalFlowPyrLK(curr_gray, prev_gray,
                                                                      new_pts, None)
                if back_pts is not None and back_status is not None:
                    fb_err = np.linalg.norm(back_pts.reshape(-1, 2) - pts.reshape(-1, 2), axis=1)
                    ok = ok & (back_status.reshape(-1) == 1) & (fb_err <= 1.5)
            if int(np.count_nonzero(ok)) < 3:
                return None
            dxs = new_pts[ok, 0, 0] - pts[ok, 0, 0]
            dys = new_pts[ok, 0, 1] - pts[ok, 0, 1]
            if self.reject_flow_bg and len(dxs) >= 5:
                spread = float(np.hypot(np.std(dxs), np.std(dys)))
                if spread > max(4.0, 0.6 * float(np.hypot(bw, bh))):
                    return None
            dx = float(np.median(dxs))
            dy = float(np.median(dys))
            return dx, dy
        except Exception:
            return None

    def _refine_low_confidence(self, obj, bbox: Tuple[float, float, float, float], score: float,
                               prev_gray: Optional[np.ndarray], curr_gray: Optional[np.ndarray],
                               recent: list) -> Tuple[Tuple[float, float, float, float], float]:
        x, y, w, h = bbox
        cx, cy = x + w / 2.0, y + h / 2.0
        candidates = [(cx, cy)]
        weights = [max(0.05, float(score))]

        kx, ky = float(obj.kalman.x[0, 0]), float(obj.kalman.x[1, 0])
        if np.isfinite(kx) and np.isfinite(ky):
            candidates.append((kx, ky))
            weights.append(0.6)

        if len(recent) >= 3:
            vx = (recent[-1][0] - recent[-3][0]) / 2.0
            vy = (recent[-1][1] - recent[-3][1]) / 2.0
            candidates.append((recent[-1][0] + vx, recent[-1][1] + vy))
            weights.append(0.5)

        if recent:
            shift = self._optical_flow_shift(prev_gray, curr_gray, recent[-1], (w, h))
            if shift is not None:
                candidates.append((recent[-1][0] + shift[0], recent[-1][1] + shift[1]))
                weights.append(0.7)

        arr = np.asarray(candidates, dtype=float)
        wts = np.asarray(weights, dtype=float)
        wts = wts / float(np.sum(wts))
        rcx = float(np.sum(arr[:, 0] * wts))
        rcy = float(np.sum(arr[:, 1] * wts))
        return (rcx - w / 2.0, rcy - h / 2.0, w, h), float(np.mean(wts))

    _CENTER_WEIGHT: Optional[np.ndarray] = None

