class Controller:
    @staticmethod
    def _rms_of_column(df: pd.DataFrame, col: str, none_value=None):
        if col not in df.columns:
            return none_value
        arr = pd.to_numeric(df[col], errors='coerce').dropna().to_numpy()
        if len(arr) == 0:
            return none_value
        return float(np.sqrt(np.mean(arr ** 2)))

