        def _phys_export_states(traj_df, phys_df):
            has_traj = traj_df is not None and not traj_df.empty
            has_phys = phys_df is not None and not phys_df.empty
            return gr.Button(interactive=has_traj), gr.Button(interactive=has_phys), gr.Button(interactive=has_phys)

        def on_video_load(video_path):
            if not video_path:
                ctrl.clear_video()
                return (gr.Slider(minimum=0, maximum=1, step=1, value=0), None, 0,
                        gr.Button(interactive=False))
            fps, last_idx = ctrl.load_video(video_path)
            img = ctrl.render_overlay(ctrl.get_video_frame_image(0), 0, selected_obj_id=ctrl.state.active_obj_id)
            return (gr.Slider(minimum=0, maximum=max(last_idx, 1), step=1, value=0), img, 0,
                    gr.Button(interactive=True))

        def on_video_path_load(raw_path):
            path, note = ctrl.resolve_video_path(raw_path)
            if path is None:
                return (gr.Slider(), gr.Image(), gr.Number(), gr.Button(), note)
            slider, img, num, btn = on_video_load(path)
            return slider, img, num, btn, note

        def on_add_obj(name, mass):
            ctrl.add_object(name, float(mass))
            choices = ctrl.get_object_choices()
            new_id = choices[-1][1]
            return gr.Dropdown(choices=choices, value=new_id)

        def on_rename_obj(obj_id, new_name, frame_idx):
            choices, status = ctrl.rename_object(obj_id, new_name)
            img = ctrl.render_overlay(ctrl.get_video_frame_image(int(frame_idx)), int(frame_idx), selected_obj_id=obj_id)
            return gr.Dropdown(choices=choices, value=obj_id), status, img, ""

        def on_display_res(value, obj_id, frame_idx):
            try:
                ctrl.display_max_height = int(max(240, min(4320, int(value))))
            except (TypeError, ValueError):
                pass
            return ctrl.render_overlay(ctrl.get_video_frame_image(int(frame_idx)), int(frame_idx), selected_obj_id=obj_id)

        def on_stick_visible(visible, obj_id, frame_idx, selected):
            ctrl.overlay_flags["stick"] = bool(visible)
            keys = list(selected or [])
            if bool(visible) and "stick" not in keys:
                keys.append("stick")
            if not bool(visible) and "stick" in keys:
                keys = [k for k in keys if k != "stick"]
            img = ctrl.render_overlay(ctrl.get_video_frame_image(int(frame_idx)), int(frame_idx), selected_obj_id=obj_id)
            return img, gr.CheckboxGroup(value=keys)

        def on_add_camera(name):
            choices = ctrl.add_camera(name)
            return gr.Dropdown(choices=choices, value=ctrl.camera_manager.active_camera_id)

        def on_rename_camera(camera_id, name):
            choices = ctrl.rename_camera(camera_id, name)
            return gr.Dropdown(choices=choices, value=camera_id)

        def on_remove_camera(camera_id):
            choices = ctrl.remove_camera(camera_id)
            return gr.Dropdown(choices=choices, value=ctrl.camera_manager.active_camera_id)

        def on_camera_switch(camera_id):
            obj_choices, active_obj_id, last_idx, img, video_path = ctrl.switch_camera(camera_id)
            active_obj = ctrl.state.objects.get(active_obj_id)
            traj_df = active_obj.trajectory if active_obj is not None else None
            phys_df = active_obj.physics_data if active_obj is not None else None
            btn_p, btn_ea, btn_ev = _phys_export_states(traj_df, phys_df)
            return (gr.Dropdown(choices=obj_choices, value=active_obj_id),
                    gr.Slider(minimum=0, maximum=max(last_idx, 1), step=1, value=0),
                    img, video_path or None, 0,
                    gr.Button(interactive=bool(video_path)), btn_p, btn_ea, btn_ev)

        def on_track(video, tracker, yolo, cls_t, fwd_b, stab, obj_id,
                     appear_th, jump_px, lost_frames, yolo_bootstrap, supervised,
                     profile, mode, wd, wdir, wsp, wsz, wasp, wapp, wof, wk, wh,
                     f_start, f_end, wch, worb, wedge, wbright, orb_on, tpl_rate, smooth_s, seg_on,
                     a_gate, reacq_after, reacq_score, drop_drift, flow_bg, strict_j,
                     preset, proc_res, subpix, autofit_on, autofit_exp, center_on, csrt_f, anchor_lk,
                     point_trk, orient_bx, multi_anc, anc_max, exp_la=False,
                     damage_cond="NORMAL", center_m="auto", max_pred=5, raw_only=True):
            ctrl.state.active_obj_id = obj_id
                                                                
            ctrl.playback_cancel = True
            weights = {"distance": wd, "direction": wdir, "speed": wsp, "size": wsz, "aspect": wasp,
                       "appearance": wapp, "optical_flow": wof, "kalman": wk, "history": wh,
                       "color_hist": wch, "orb": worb, "edge": wedge, "brightness": wbright}
            status, df = ctrl.process_tracking(video, tracker, yolo, cls_t, fwd_b, stab,
                                               appearance_threshold=appear_th, max_jump_px=jump_px,
                                               max_lost_frames=lost_frames, allow_yolo_bootstrap=yolo_bootstrap,
                                               supervised=supervised, tracking_profile=profile,
                                               tracking_mode=mode, score_weights=weights,
                                               frame_start=f_start, frame_end=f_end,
                                               use_orb=orb_on, template_update_rate=tpl_rate,
                                               smooth_strength=smooth_s, auto_segment=seg_on,
                                               anchor_gate=a_gate, reacquire_after=reacq_after,
                                               reacquire_min_score=reacq_score,
                                               drop_drift_rows=drop_drift, reject_flow_bg=flow_bg,
                                               strict_jump=strict_j, speed_preset=preset,
                                               process_res=proc_res, subpixel_refine=subpix,
                                               autofit_bbox=autofit_on, autofit_expand=autofit_exp,
                                               center_lock=center_on, csrt_fast=csrt_f,
                                               anchor_lock=anchor_lk, use_point_tracking=point_trk,
                                               orient_box=orient_bx, use_multi_anchor=multi_anc,
                                               anchor_bank_max=anc_max,
                                               experimental_lookahead=exp_la,
                                                                                     
                                               damage_condition=damage_cond,
                                               center_method=center_m,
                                               max_predicted_run=max_pred,
                                               raw_tracking_only=raw_only)
            pause_frame = getattr(ctrl.video_processor, "last_pause_frame", None)
            start_at = int(pause_frame) if pause_frame is not None else 0
            traj_df, phys_df, ai_sum, img, fig3d, fig_m, fig_p, cur = ctrl.get_object_snapshot(obj_id, start_at)
            total = ctrl.get_total_frames(obj_id)
            btn_p, btn_ea, btn_ev = _phys_export_states(traj_df, phys_df)
            return (status, _ui_table(traj_df), _ui_table(phys_df), ai_sum,
                    gr.Slider(minimum=0, maximum=max(total, 1), step=1, value=min(int(cur), max(total, 1))),
                    img, fig3d, fig_m, fig_p, cur, btn_p, btn_ea, btn_ev)

        def on_repair(obj_id, method, frame_idx):
            traj_df, phys_df, ai_sum = ctrl.repair_trajectory(obj_id, method)
            img, fig3d, fig_m, fig_p = ctrl.sync_to_frame(obj_id, int(frame_idx))
            return _ui_table(traj_df), _ui_table(phys_df), ai_sum, img, fig3d, fig_m, fig_p

        def on_compute_phys(obj_id, scale_v, origin_x, origin_y, ang, cur_frame):
            df, _, _, _, ai_sum = ctrl.compute_full_physics(obj_id, scale_v, origin_x, origin_y, ang)
            total = ctrl.get_total_frames(obj_id)
            cur = max(0, min(int(cur_frame), total))
            img, fig3d, fig_m, fig_p = ctrl.sync_to_frame(obj_id, cur)
            has_phys = not df.empty
            return (_ui_table(df), fig3d, fig_m, fig_p, ai_sum,
                    gr.Slider(minimum=0, maximum=max(total, 1), step=1, value=min(int(cur), max(total, 1))), min(int(cur), max(total, 1)),
                    gr.Button(interactive=has_phys), gr.Button(interactive=has_phys))

        def on_tables_refresh(obj_id):
            summary = ctrl.build_physics_summary_table(obj_id)
            full = _ui_table(ctrl.build_physics_full_table(obj_id))
            if summary is None or getattr(summary, "empty", True):
                return summary, full, _MSG["no_data"]
            return summary, full, TB["summary_desc"]

        def on_tables_export(obj_id):
            status, paths = ctrl.export_physics_tables(obj_id)
            return status, (paths if paths else None)

        def on_plot_point_click(obj_id, evt: gr.SelectData):
            target = ctrl.resolve_frame_from_plot(obj_id, getattr(evt, "index", None),
                                                 getattr(evt, "value", None))
            total = ctrl.get_total_frames(obj_id)
            img, fig3d, fig_m, fig_p = ctrl.sync_to_frame(obj_id, int(target))
            return (gr.Slider(minimum=0, maximum=max(total, 1), step=1, value=int(target)),
                    int(target), img, fig3d, fig_m, fig_p)

        def on_click_followup(obj_id, frame_idx, threshold):
            axis_fig = ctrl.get_axis_figure(obj_id, int(frame_idx))
            refresh = on_state_refresh(obj_id)
            ctrl.suspicious_conf_threshold = float(threshold)
            table = ctrl.get_suspicious_frames(obj_id, threshold)
            status = ctrl.build_check_status(obj_id, threshold)
            return (axis_fig,) + tuple(refresh) + (table, status)

        _axis_outputs = None

        def _axis_apply(obj_id, frame_idx, angle_value, status_text=None):
            traj, phys, ai_sum, applied = ctrl.set_axis_angle(obj_id, angle_value)
            img, fig3d, fig_m, fig_p = ctrl.sync_to_frame(obj_id, int(frame_idx))
            msg = status_text if status_text is not None else C["axis_tilt_applied"].format(angle=applied)
            return (img, _ui_table(traj), _ui_table(phys), ai_sum,
                    fig3d, fig_m, fig_p, gr.Number(value=applied), gr.Slider(value=applied), msg)

        def on_axis_tilt(obj_id, frame_idx, angle_value):
            return _axis_apply(obj_id, frame_idx, angle_value)

        def on_axis_nudge(delta):
            def _run(obj_id, frame_idx):
                base = ctrl.get_axis_angle(obj_id)
                return _axis_apply(obj_id, frame_idx, base + float(delta))
            return _run

        def on_axis_snap(value):
            def _run(obj_id, frame_idx):
                return _axis_apply(obj_id, frame_idx, float(value))
            return _run

        def on_axis_align(obj_id, frame_idx):
            traj, phys, msg, applied = ctrl.align_axis_to_motion(obj_id)
            img, fig3d, fig_m, fig_p = ctrl.sync_to_frame(obj_id, int(frame_idx))
            return (img, _ui_table(traj), _ui_table(phys), "",
                    fig3d, fig_m, fig_p, gr.Number(value=applied), gr.Slider(value=applied), msg)

        def on_axis_style(length_px, tick_px, obj_id, frame_idx):
            try:
                ctrl.axis_overlay_length = float(max(20.0, float(length_px)))
            except (TypeError, ValueError):
                pass
            try:
                ctrl.axis_tick_px = float(max(4.0, float(tick_px)))
            except (TypeError, ValueError):
                pass
            return ctrl.render_overlay(ctrl.get_video_frame_image(int(frame_idx)), int(frame_idx),
                                       selected_obj_id=obj_id)

        def on_bidir_validate(obj_id, video, trk, tol, frame_idx):
            ctrl.bidirectional_tolerance_px = float(tol or 5.0)
            status, table = ctrl.run_bidirectional_validation(obj_id, video, trk, tol)
            img = ctrl.render_overlay(ctrl.get_video_frame_image(int(frame_idx)), int(frame_idx),
                                      selected_obj_id=obj_id)
            return status, table, img

        def on_phys_warning_toggle(flag):
            ctrl.physics_warning_check = bool(flag)
            return None

        def on_cusp_setting(deg, ratio):
            try:
                ctrl.cusp_deg = float(np.clip(float(deg), 30.0, 179.0))
            except (TypeError, ValueError):
                pass
            try:
                ctrl.cusp_speed_ratio = float(np.clip(float(ratio), 0.02, 0.98))
            except (TypeError, ValueError):
                pass
            return None

        def on_sharp_turn_setting(deg, min_px):
            try:
                ctrl.sharp_turn_deg = float(np.clip(float(deg), 5.0, 179.0))
            except (TypeError, ValueError):
                pass
            try:
                ctrl.sharp_turn_min_px = float(max(0.0, float(min_px)))
            except (TypeError, ValueError):
                pass
            return None

        def on_build_clip(obj_id, frame_idx, count, step, height, quality):
            html, status = ctrl.build_playback_clip(obj_id, int(frame_idx), int(count), int(step),
                                                    int(height), int(quality))
            return html, status

        def on_language_change(lang):
            try:
                applied = set_language(lang)
            except Exception as exc:
                logger.warning(f"언어 변경 실패: {exc}")
                return ""
            block = get_strings().get("language", {}) or {}
            key = "applied" if applied == "en" else "applied_ko"
            return str(block.get(key, "") or block.get("applied", "") or "")

        def on_export_images(obj_id, graphs, tables, frame_spec, include_frames, full_res, fmt,
                             f_var, f_type, fl_var, fl_type, cut, fam):
            status, paths = ctrl.export_selected_images(
                obj_id, graphs, tables, frame_spec, fmt, include_frames, full_res,
                f_var, f_type, fl_var, fl_type, cut, fam)
            return status, (paths if paths else None)

        def on_manual_plot(text, file_obj, name, fit_type, overlay, obj_id, xlab, ylab):
            path = None
            if file_obj is not None:
                path = getattr(file_obj, "name", None) or (file_obj if isinstance(file_obj, str) else None)
            fig, status, table = ctrl.plot_manual_data(text, path, name, fit_type, overlay, obj_id, xlab, ylab)
