        def on_checkerboard(cols_n, rows_n, square_m, obj_id, frame_idx):
            frame = ctrl.get_video_frame_image(int(frame_idx))
            if frame is None:
                return _MSG["no_video"], gr.Number(), None
            try:
                bgr = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)
                pattern = (max(2, int(cols_n or 9)), max(2, int(rows_n or 6)))
                scale = AutoScaleCalibrator.detect_checkerboard_scale(bgr, pattern, float(square_m or 0.025))
            except Exception:
                scale = None
            img = ctrl.render_overlay(ctrl.get_video_frame_image(int(frame_idx)), int(frame_idx), selected_obj_id=obj_id)
            if scale is None or not np.isfinite(scale) or scale <= 0:
                return RS["cb_failed"], gr.Number(), img
            obj = ctrl.state.objects.get(obj_id)
            if obj is not None:
                obj.scale_m_px = float(scale)
                obj.calibrated = True
                obj.scale_unit = "m"
                ctrl._recompute_physics_if_needed(obj_id)
            img = ctrl.render_overlay(ctrl.get_video_frame_image(int(frame_idx)), int(frame_idx), selected_obj_id=obj_id)
            return RS["cb_success"].format(scale=float(scale)), gr.Number(value=float(scale)), img

