        def on_run_3d(cam1_id, cam2_id, cam3_id, use_list, obj_id, offset, offset3,
                      interp, max_err, refine_on, reject_on,
                      min_angle, max_speed, hampel, fill_gap, drop_bad):
            picks = [str(v) for v in (use_list or ["1", "2"])]
            mapping = {"1": (cam1_id, 0.0), "2": (cam2_id, offset), "3": (cam3_id, offset3)}
            ids, offs = [], []
            for key in ("1", "2", "3"):
                if key in picks and mapping[key][0]:
                    ids.append(mapping[key][0])
                    try:
                        offs.append(float(mapping[key][1] or 0.0))
                    except (TypeError, ValueError):
                        offs.append(0.0)
            df3d, fig, note = ctrl.run_3d_reconstruction_multi(
                ids, obj_id, time_offsets=offs, interp_method=interp,
                max_reprojection_error=max_err, refine=refine_on,
                reject_outlier_views=reject_on,
                min_ray_angle_deg=float(min_angle or 0.0),
                max_speed_3d=float(max_speed or 0.0),
                hampel_sigma=float(hampel or 4.5),
                fill_gap_frames=int(fill_gap or 0),
                drop_invalid=bool(drop_bad))
            return df3d, fig, note, ctrl.build_3d_validation_table()

