        _TH_KEYS = ["confidence_min", "bounding_box_change", "frame_distance", "direction_change",
                    "velocity_change", "acceleration_change", "jerk", "pitch_change", "wobble_change",
                    "angular_velocity_change", "angular_acceleration_change"]

        def on_validate(obj_id, *values):
            thresholds = {k: v for k, v in zip(_TH_KEYS, values[:len(_TH_KEYS)])}
            levels = dict(zip(["caution", "warning", "critical"], values[len(_TH_KEYS):len(_TH_KEYS) + 3]))
            auto_flag = bool(values[len(_TH_KEYS) + 3]) if len(values) > len(_TH_KEYS) + 3 else True
            result = ctrl.run_physics_validation(obj_id, thresholds, levels, auto=auto_flag)
            cards = ctrl.build_validation_summary(obj_id)
            table = ctrl.build_warning_table(obj_id)
            fig = ctrl.build_validation_plot(obj_id)
            if result is None or result.empty:
                return cards, table, fig, PV["empty"], gr.Image()
            total = int(len(result))
            warned = int(result['physics_warning'].sum())
            status = PV["done"].format(total=total, warned=warned,
                                       ratio=(warned / total * 100.0) if total else 0.0)
            img = ctrl.render_overlay(ctrl.get_video_frame_image(0), 0, selected_obj_id=obj_id)
            return cards, table, fig, status, img

        def on_auto_threshold(obj_id):
            suggested = ctrl.suggest_validation_thresholds(obj_id)
            return (gr.Number(value=suggested.get("confidence_min")),
                    gr.Number(value=suggested.get("bounding_box_change")),
                    gr.Number(value=suggested.get("frame_distance")),
                    gr.Number(value=suggested.get("direction_change")),
                    gr.Number(value=suggested.get("velocity_change")),
                    gr.Number(value=suggested.get("acceleration_change")),
                    gr.Number(value=suggested.get("jerk")),
                    gr.Number(value=suggested.get("pitch_change")),
                    gr.Number(value=suggested.get("wobble_change")),
                    gr.Number(value=suggested.get("angular_velocity_change")),
                    gr.Number(value=suggested.get("angular_acceleration_change")),
                    PV["auto_done"])

        def on_warning_select(obj_id, evt: gr.SelectData):
            table = ctrl.build_warning_table(obj_id)
            if table.empty:
                return gr.Slider(), gr.Image(), 0, ""
            index = getattr(evt, "index", None)
            row_idx = index[0] if isinstance(index, (list, tuple)) and index else 0
            try:
                row_idx = int(row_idx)
            except (TypeError, ValueError):
                row_idx = 0
            row_idx = max(0, min(row_idx, len(table) - 1))
            frame = int(table.iloc[row_idx][PV["col_frame"]])
            total = ctrl.get_total_frames(obj_id)
            img, fig3d, fig_m, fig_p = ctrl.sync_to_frame(obj_id, frame)
            return (gr.Slider(minimum=0, maximum=max(total, 1), step=1, value=min(int(frame), max(total, 1))),
                    img, min(int(frame), max(total, 1)), PV["jump_done"].format(frame=frame))

