        def on_aruco(marker_length, obj_id, frame_idx):
            frame = ctrl.get_video_frame_image(int(frame_idx))
            if frame is None:
                return _MSG["no_video"], gr.Number(), None
            try:
                bgr = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)
                scale = AutoScaleCalibrator.detect_aruco_scale(bgr, float(marker_length or 0.05))
            except Exception:
                scale = None
            if scale is None or not np.isfinite(scale) or scale <= 0:
                img = ctrl.render_overlay(ctrl.get_video_frame_image(int(frame_idx)), int(frame_idx), selected_obj_id=obj_id)
                return _MSG["aruco_failed"], gr.Number(), img
            obj = ctrl.state.objects.get(obj_id)
            if obj is not None:
                obj.scale_m_px = float(scale)
                obj.calibrated = True
                obj.scale_unit = "m"
                ctrl._recompute_physics_if_needed(obj_id)
            img = ctrl.render_overlay(ctrl.get_video_frame_image(int(frame_idx)), int(frame_idx), selected_obj_id=obj_id)
            return _MSG["aruco_success"].format(scale=float(scale)), gr.Number(value=float(scale)), img

        def on_generate_graphs(obj_id, selections, var_fit, type_fit, var_filter, type_filter, cutoff, family,
                               x_var_fit="t"):
            selections = selections or []
            if not selections:
                ctrl.graph_generated = False
                return tuple([ST["no_graph_selected"]] + [gr.Plot(visible=False) for _ in _GRAPH_ORDER])
            figures = ctrl.build_selected_plots(obj_id, selections, var_fit, type_fit, var_filter, type_filter,
                                               cutoff, family, x_var_fit)
            updates = []
            for key in _GRAPH_ORDER:
                fig = figures.get(key)
                if fig is None:
                    updates.append(gr.Plot(visible=False))
                else:
                    updates.append(gr.Plot(value=fig, visible=True))
            return tuple([ST["graph_done"]] + updates)

